-- Merges real rounds from the BF2Statistics database into the session log.
-- * 19 existing rows (spreadsheet + admin entries) are matched to a real round on
--   map, player count and result; they keep their size and difficulty and gain the
--   real date (US Eastern) and a link to the stats round; their bot count is kept.
-- * The remaining 3-6 player rounds are inserted new. Size follows your play pattern:
--   3-4 players = smallest size the map has, 5-6 players = 64, Urban Decay/Urban Jungle = 32, City District 5-6p = 32.
-- * The 3-player Falklands win is moved from size 16 to 32 (Falklands has no 16).
-- * Rounds with 1-2 or 7+ human players are not imported (the site models 3-6).
-- Safe to re-run. Run after 003_map_size_data.sql and 004_allow_null_played_at.sql.

alter table public.bf2_game_logs add column if not exists stats_round_id bigint unique;

-- Link existing rows to their real round
update public.bf2_game_logs set played_at = '2025-05-08', stats_round_id = 11, notes = 'Date from stats round #11 (size, bots and difficulty from spreadsheet)' where id = 'bdaae828-3584-45e8-989a-96c3aaba7c40' and stats_round_id is null;  -- Devil's Perch 3p win
